static int32_t asr(int32_t a,unsigned n){return a>=0?(int32_t)((uint32_t)a>>n):si(((uint32_t)a>>n)|(~UINT32_C(0)<<(32-n)));}
static int32_t clip(int32_t a){return a< -32767? -32767:a>32767?32767:a;}
static int32_t smooth(int32_t a,int32_t target,int32_t speed){return add(a,mul(sub(target,asr(a,15)),speed));}
static void hz(chfx_history *h){h->next=0;h->valid=0;}
static void hb(chfx_history *h,int16_t *p,uint32_t n){h->data=p;h->size=n;hz(h);}
int16_t chfx_history_age(const chfx_history *h,uint32_t age){assert(h&&h->data&&age&&age<=h->size);if(age>h->valid)return 0;int32_t i=(int32_t)h->next-(int32_t)age;if(i<0)i+=(int32_t)h->size;return h->data[i];}
static int32_t peek(chfx_history *h,uint32_t lag){return chfx_history_age(h,lag?lag:h->size);}
static int32_t current_peek(chfx_history *h,uint32_t lag,int32_t current){return lag?chfx_history_age(h,lag):current;}
static void push(chfx_history *h,int32_t value){h->data[h->next]=(int16_t)value;if(h->valid<h->size)++h->valid;if(++h->next==h->size)h->next=0;}
static void hook(const chfx_hooks *h,uint32_t i){if(h&&h->before_frame)h->before_frame(h->context,i);}
void chfx_short_construct(chfx_short *s){memset(s,0,sizeof *s);s->dirty=1;chfx_short_edit(s,2,0);chfx_short_edit(s,3,0);}
void chfx_bpm_construct(chfx_bpm *s){memset(s,0,sizeof *s);s->bpm=120;s->max_division=13;s->delay_target=1378;s->gain_target=32767;}
void chfx_gate_construct(chfx_gate *s){memset(s,0,sizeof *s);s->dirty=1;s->gate_phase=1;s->hold_counter=INT32_MAX;const int defaults[7]={30,100,85,80,63,0,40};for(unsigned i=0;i<7;++i)chfx_gate_native(s,i,defaults[i]);}
void chfx_hall_construct(chfx_hall *s){memset(s,0,sizeof *s);s->dirty=1;s->idle=1;}
int chfx_short_bind(chfx_short *s,int16_t *p,size_t n){if(!s||!p||n<CHFX_SHORT_SLOTS)return 0;hb(s->history,p,16384);hb(s->history+1,p+16384,16384);return 1;}
int chfx_bpm_bind(chfx_bpm *s,int16_t *p,size_t n){if(!s||!p||n<CHFX_BPM_STEREO_SLOTS)return 0;hb(s->history,p,CHFX_BPM_CHANNEL_SLOTS);hb(s->history+1,p+CHFX_BPM_CHANNEL_SLOTS,CHFX_BPM_CHANNEL_SLOTS);return 1;}
int chfx_gate_bind(chfx_gate *s,int16_t *p,size_t n){if(!s||!p||n<CHFX_GATE_SLOTS)return 0;const uint32_t lengths[5]={2669,2824,969,2301,1676};for(unsigned i=0;i<5;++i){hb(s->history+i,p,lengths[i]);p+=lengths[i];}return 1;}
int chfx_hall_bind(chfx_hall *s,int16_t *p,size_t n){if(!s||!p||n<CHFX_HALL_SLOTS)return 0;hb(s->history,p,442);p+=442;for(unsigned i=0;i<4;++i){hb(s->history+1+i,p,hall_A_delay[i]);p+=hall_A_delay[i];}for(unsigned i=0;i<4;++i){hb(s->history+5+i,p,hall_B_delay[i]);p+=hall_B_delay[i];}return 1;}
void chfx_short_reset(chfx_short *s){for(unsigned i=0;i<2;++i)hz(s->history+i);s->delay_acc=shl(s->delay_target,15);s->feedback_acc=shl(s->feedback_target,15);}
void chfx_bpm_reset(chfx_bpm *s){for(unsigned i=0;i<2;++i)hz(s->history+i);s->feedback[0]=s->feedback[1]=0;s->gain_acc=shl(s->gain_target,15);s->feedback_acc=shl(s->feedback_target,15);s->delay_acc=shl(s->delay_target,12);}
void chfx_gate_reset(chfx_gate *s){for(unsigned i=0;i<5;++i)hz(s->history+i);s->level_acc=shl(s->level_target,15);s->level_current=s->level_target;s->feedback_acc=shl(s->feedback_target,15);s->feedback_current=s->feedback_target;s->input_acc=shl(s->input_target,15);s->gate_phase=1;s->gate_envelope=32767;s->hold_counter=INT32_MAX;s->detector=0;}
void chfx_hall_reset(chfx_hall *s){for(unsigned i=0;i<9;++i)hz(s->history+i);memset(s->A_state,0,sizeof s->A_state);memset(s->A_output,0,sizeof s->A_output);memset(s->B_state,0,sizeof s->B_state);s->level_acc=s->level_target;}
int chfx_short_edit(chfx_short *s,unsigned p,int v){v&=127;if(p==2)s->time=v;else if(p==3)s->depth=v;else return 0;int d=fx_time_curve[s->time];if(d<5)d=5;s->pending_delay=asr(mul(16383,d),15);s->pending_feedback=asr(mul(short_feedback_curve[s->time],fx_depth_curve[s->depth]),15);s->dirty=1;return v;}
static void bpm_delay(chfx_bpm *s){int i=bpm_division[s->time];if(i>s->max_division)i=s->max_division;s->delay_target=bpm_numerator[i]/s->bpm;}
int chfx_bpm_edit(chfx_bpm *s,unsigned p,int v){v&=127;if(p==2){s->time=v;bpm_delay(s);}else if(p==3)s->depth=v;else return 0;int32_t a=32767-asr(fx_level_curve[s->time],3);int32_t b=asr(mul(fx_depth_curve[s->depth],29491),15);int32_t product=mul(a,b);s->feedback_target=asr(product,15);s->gain_target=sub(32767,asr(product,16));return v;}
void chfx_bpm_tempo(chfx_bpm *s,int32_t deci){s->bpm=deci/10;assert(s->bpm>=20&&s->bpm<=400);int maximum=0;for(int i=0;i<14;++i)if((uint32_t)(s->bpm*131072)>(uint32_t)bpm_numerator[i])maximum=i;s->max_division=maximum;bpm_delay(s);}
int chfx_gate_native(chfx_gate *s,unsigned p,int v){assert(v>=0&&v<=127);if(p>6)return 0;s->parameters[p]=v;switch(p){case 0:s->hold_step=(int32_t)gate_hold[v];break;case 2:s->threshold=gate_threshold[v];break;case 5:s->attack=(int32_t)(16777215u-gate_attack[v]);break;case 6:s->release=(int32_t)gate_release[v];break;default:s->pending_feedback=20480+asr(mul(gate_color[s->parameters[4]],5),4);s->pending_level=gate_level[s->parameters[1]];s->pending_input=asr(gate_level[s->parameters[3]],2);s->dirty=1;break;}return v;}
int chfx_gate_edit(chfx_gate *s,unsigned p,int v){if(p<2||p>3)return 0;return chfx_gate_native(s,p-2,v);}
int chfx_hall_edit(chfx_hall *s,unsigned p,int v){v&=127;if(p==2)s->time=v;else if(p==3)s->level=v;else return 0;s->pending_time=s->time;s->pending_level=fx_level_curve[s->level];s->dirty=1;return v;}
void chfx_short_fast(chfx_short *s,int x){s->fast=(uint8_t)x;}void chfx_bpm_fast(chfx_bpm *s,int x){s->fast=(uint8_t)x;}void chfx_gate_fast(chfx_gate *s,int x){s->fast=(uint8_t)x;}
void chfx_hall_fast(chfx_hall *s,int x){(void)s;(void)x;}
void chfx_short_event(chfx_short *s,unsigned t){if(t==5)chfx_short_reset(s);}void chfx_bpm_event(chfx_bpm *s,unsigned t){if(t==5)chfx_bpm_reset(s);}void chfx_gate_event(chfx_gate *s,unsigned t){if(t==5)chfx_gate_reset(s);}void chfx_hall_event(chfx_hall *s,unsigned t){if(t==5)chfx_hall_reset(s);}
static int32_t short_feedback(int32_t v,int32_t coefficient){int32_t u=sub(shl(v,15),v),a=asr(u,15),b=asr(mul(a,coefficient),15);if((uint32_t)u>=32768u&&a==b){int32_t magnitude=a<0?-a:a;return v>1?magnitude-1:1-magnitude;}return b;}
void chfx_short_process(chfx_short *s,int16_t *L,int16_t *R,size_t n,const chfx_hooks *h){assert(n<=CHFX_MAX_BLOCK&&s->history[0].data&&s->history[1].data);for(size_t i=0;i<n;++i){hook(h,(uint32_t)i);if(!(i&63)&&s->dirty){s->delay_target=s->pending_delay;s->feedback_target=s->pending_feedback;s->dirty=0;}int speed=s->fast?32767:102;s->delay_acc=smooth(s->delay_acc,s->delay_target,speed);s->feedback_acc=smooth(s->feedback_acc,s->feedback_target,speed);uint32_t lag=(uint32_t)asr(s->delay_acc,15),f=(uint32_t)s->delay_acc&32767u;int32_t delayed[2];for(unsigned ch=0;ch<2;++ch){int32_t a=peek(s->history+ch,lag),b=peek(s->history+ch,lag+1);int32_t v=add(a,asr(mul(sub(b,a),(int32_t)f),15));delayed[ch]=short_feedback(v,asr(s->feedback_acc,15));}int32_t gain=sub(32767,asr(s->feedback_acc,16));int32_t l=clip(add(asr(mul(gain,L[i]),15),delayed[1])),r=clip(add(asr(mul(gain,R[i]),15),delayed[0]));push(s->history,l);push(s->history+1,r);L[i]=(int16_t)l;R[i]=(int16_t)r;s->original_write=(s->original_write+1u)&16383u;}}
