static void hall_core(chfx_hall *s,int16_t *L,int16_t *R,size_t n,const chfx_hooks *h){assert(n<=CHFX_MAX_BLOCK&&s->history[0].data);for(size_t i=0;i<n;++i){hook(h,(uint32_t)i);if(!(i&63)&&s->dirty){s->current_time=s->pending_time;s->level_target=s->pending_level;for(unsigned j=0;j<4;++j)s->B_coeff[j]=hall_time_coeff[s->current_time*4+j];s->dirty=0;}s->level_acc=smooth(s->level_acc,s->level_target,102);int32_t l=L[i]< -32767?-32767:L[i],r=R[i]< -32767?-32767:R[i];int32_t input=clip(asr(mul(add(l,r),9830),15));int32_t predelayed=current_peek(s->history,442,input);push(s->history,input);predelayed=clip(add(predelayed,asr(mul(input,3932),15)));int32_t Ainput[4]={predelayed,s->A_state[1],s->A_state[2],s->A_state[3]};for(unsigned j=0;j<4;++j){int32_t d=peek(s->history+1+j,hall_A_delay[j]);int32_t v=add(Ainput[j],asr(mul(hall_A_coeff[j],d),15));push(s->history+1+j,clip(v));s->A_output[j]=(int16_t)clip(sub(d,asr(mul(v,hall_A_coeff[j]),15)));}s->A_state[1]=s->A_output[0];for(unsigned j=0;j<4;++j){int32_t d=peek(s->history+5+j,hall_B_delay[j]);int32_t v=clip(add(s->A_output[1],asr(mul(s->B_coeff[j],d),15)));int32_t out=clip(sub(asr(mul(add(v,s->B_state[j]),hall_damping[j]),15),v));s->B_state[j]=(int16_t)out;push(s->history+5+j,out);}int32_t sumL=0,sumR=0;for(unsigned j=0;j<4;++j){sumL=add(sumL,chfx_history_age(s->history+5+j,hall_L_tap[j]+1u));sumR=add(sumR,chfx_history_age(s->history+5+j,hall_R_tap[j]+1u));}s->A_state[2]=(int16_t)clip(asr(sumL,1));s->A_state[3]=(int16_t)clip(asr(sumR,1));L[i]=(int16_t)clip(add(l,asr(mul(asr(s->level_acc,15),s->A_output[2]),15)));R[i]=(int16_t)clip(add(r,asr(mul(asr(s->level_acc,15),s->A_output[3]),15)));--s->original_counter;}}

/* OriginalBasicEffectAdapterc4000 signed16peak treats abs(-32768) as negative
 * and therefore ignores it. The whole invocation is scanned before processing. */
static int audible(const int16_t *L,const int16_t *R,size_t n){for(size_t i=0;i<n;++i)if((L[i]!=0&&L[i]!=INT16_MIN)||(R[i]!=0&&R[i]!=INT16_MIN))return 1;return 0;}
void chfx_hall_process(chfx_hall *s,int16_t *L,int16_t *R,size_t n,const chfx_hooks *h){
 assert(n<=CHFX_MAX_BLOCK&&s->history[0].data);
 if(s->idle){if(!n||!audible(L,R,n))return;s->idle=0;s->idle_remaining=48000;}
 hall_core(s,L,R,n,h);
 if(n&&audible(L,R,n)){s->idle_remaining=48000;return;}
 if(s->idle_remaining>n)s->idle_remaining-=n;else{s->idle_remaining=0;s->idle=1;}
}

void chfx_hall_begin(chfx_hall *s){s->core_active=1;}
void chfx_hall_retire(chfx_hall *s){s->core_active=0;}
void chfx_short_queued_event(chfx_short *s,unsigned t){if(t==4)chfx_short_reset(s);}
void chfx_bpm_queued_event(chfx_bpm *s,unsigned t){if(t==4)chfx_bpm_reset(s);}
void chfx_gate_queued_event(chfx_gate *s,unsigned t){if(t==4)chfx_gate_reset(s);}
